<?php
namespace App\Services\Reports\Providers;
use App\Enums\OperationalReportType;use App\Models\Request as SupplyRequest;use App\Models\User;use App\Services\Reports\AbstractOperationalReportProvider;use Illuminate\Contracts\Pagination\CursorPaginator;use Illuminate\Database\Eloquent\Builder;
final class RequestsReportProvider extends AbstractOperationalReportProvider{
public function type():OperationalReportType{return OperationalReportType::REQUESTS;}protected function label():string{return 'تقرير حركة الطلبات';}protected function description():string{return 'طلبات التوريد وحالاتها ونوع البيع وقيمتها.';}protected function viewPermission():string{return 'requests.report';}protected function exportPermission():string{return 'requests.export';}protected function scopes():array{return ['network','pos'];}protected function posSelection():string{return 'optional';}protected function statusChoices():array{return ['PENDING','APPROVED','REJECTED','CANCELLED'];}protected function saleTypeChoices():array{return ['CASH','CREDIT'];}
protected function columns():array{return [['id'=>'request_id','label'=>'رقم الطلب','data_type'=>'integer'],['id'=>'request_uuid','label'=>'مرجع الطلب','data_type'=>'text'],['id'=>'request_date','label'=>'التاريخ','data_type'=>'date'],['id'=>'pos_id','label'=>'نقطة البيع','data_type'=>'integer'],['id'=>'sale_type','label'=>'نوع البيع','data_type'=>'text'],['id'=>'status','label'=>'الحالة','data_type'=>'text'],['id'=>'request_total_amount','label'=>'الإجمالي','data_type'=>'decimal'],['id'=>'request_note','label'=>'البيان','data_type'=>'text']];}
protected function metricSlots():array{return [['id'=>'record_count','label'=>'عدد الطلبات','data_type'=>'integer'],['id'=>'total_amount','label'=>'قيمة الطلبات','data_type'=>'decimal'],['id'=>'pending_count','label'=>'قيد الانتظار','data_type'=>'integer'],['id'=>'approved_count','label'=>'معتمدة','data_type'=>'integer'],['id'=>'rejected_count','label'=>'مرفوضة','data_type'=>'integer'],['id'=>'cancelled_count','label'=>'ملغاة','data_type'=>'integer']];}protected function summaryCharts():array{return [['id'=>'requests_by_status','label'=>'الطلبات حسب الحالة','chart_type'=>'bar','value_key'=>'record_count','label_key'=>'status']];}
private function query(int $networkId,?int $posId,array $filters):Builder{$p=$this->pattern($filters);$q=SupplyRequest::query()->with('pos')->where('network_id',$networkId)->when($posId!==null,fn(Builder $q):Builder=>$q->where('pos_id',$posId))->when($filters['status']??null,fn(Builder $q,string $v):Builder=>$q->where('status',$v))->when($filters['sale_type']??null,fn(Builder $q,string $v):Builder=>$q->where('sale_type',$v))->when($p!==null,fn(Builder $q):Builder=>$q->where(fn(Builder $n):Builder=>$n->where('request_uuid','like',$p)->orWhere('request_note','like',$p)));return $this->applyDates($q,'request_date',$filters);}
public function build(User $user,int $networkId,?int $posId,array $filters):CursorPaginator{return $this->paginate($this->query($networkId,$posId,$filters),$filters,'request_date','request_id');}
public function summary(User $user,int $networkId,?int $posId,array $filters):array{$q=$this->query($networkId,$posId,$filters);$groups=(clone $q)->reorder()->selectRaw('status, COUNT(*) as record_count')->groupBy('status')->get();return ['record_count'=>(clone $q)->count(),'total_amount'=>$this->amountValue((clone $q)->sum('request_total_amount')),'pending_count'=>(clone $q)->where('status','PENDING')->count(),'approved_count'=>(clone $q)->where('status','APPROVED')->count(),'rejected_count'=>(clone $q)->where('status','REJECTED')->count(),'cancelled_count'=>(clone $q)->where('status','CANCELLED')->count(),'currency_code'=>$this->currencyCode($networkId),'charts'=>['requests_by_status'=>$groups->map(fn($r)=>['status'=>$r->status instanceof \BackedEnum?$r->status->value:$r->status,'record_count'=>(int)$r->record_count])->all()]];}
public function exportColumns():array{return ['request_id'=>'رقم الطلب','request_uuid'=>'مرجع الطلب','request_date'=>'التاريخ','pos_id'=>'نقطة البيع','sale_type'=>'نوع البيع','status'=>'الحالة','request_total_amount'=>'الإجمالي','request_note'=>'البيان'];}
public function serializeExportRow(mixed $r):array{return ['request_id'=>$r->request_id,'request_uuid'=>$r->request_uuid,'request_date'=>$this->dateValue($r->request_date),'pos_id'=>$r->pos_id,'sale_type'=>$this->enumValue($r->sale_type),'status'=>$this->enumValue($r->status),'request_total_amount'=>$this->amountValue($r->request_total_amount),'request_note'=>$r->request_note];}
}